import os
import uuid
from fastapi import FastAPI, UploadFile, File
from fastapi.responses import JSONResponse, HTMLResponse
import uvicorn
import librosa
import soundfile as sf
import pickle
import torch
import nemo.collections.asr as nemo_asr
import numpy as np
import io
import base64
import matplotlib.pyplot as plt

app = FastAPI(title="Voice Anti-Spoofing API")

speaker_model = None
clf_model = None

@app.on_event("startup")
def load_models():
    global speaker_model, clf_model
    print("Cargando modelos en memoria al iniciar el servidor...")
    speaker_model = nemo_asr.models.EncDecSpeakerLabelModel.from_pretrained(model_name="titanet_large")
    speaker_model.eval()
    
    if os.path.exists("anti_spoofing_model.pkl"):
        with open("anti_spoofing_model.pkl", "rb") as f:
            clf_model = pickle.load(f)
    else:
        print("ADVERTENCIA: No se encontró anti_spoofing_model.pkl")

def generate_spectrogram_base64(y, sr):
    plt.figure(figsize=(10, 4))
    S = librosa.feature.melspectrogram(y=y, sr=sr, n_mels=128)
    S_dB = librosa.power_to_db(S, ref=np.max)
    librosa.display.specshow(S_dB, sr=sr, x_axis='time', y_axis='mel')
    plt.colorbar(format='%+2.0f dB')
    plt.title('Espectrograma de Frecuencias (Huella Vocal)')
    plt.tight_layout()
    buf = io.BytesIO()
    plt.savefig(buf, format='png')
    plt.close()
    buf.seek(0)
    return base64.b64encode(buf.read()).decode('utf-8')

@app.post("/save_human_sample")
async def save_human_sample(file: UploadFile = File(...)):
    # Guardar audio en la carpeta para el entrenamiento híbrido
    os.makedirs("dataset_laptop", exist_ok=True)
    temp_input = f"temp_save_{uuid.uuid4().hex}"
    with open(temp_input, "wb") as buffer:
        buffer.write(await file.read())
    y, sr = librosa.load(temp_input, sr=16000, mono=True)
    final_path = f"dataset_laptop/laptop_human_{uuid.uuid4().hex}.wav"
    sf.write(final_path, y, 16000)
    os.remove(temp_input)
    return {"status": "ok"}

@app.post("/detect_visual")
async def detect_visual(file: UploadFile = File(...)):
    if not clf_model:
        return JSONResponse(content={"error": "El modelo no está cargado."}, status_code=500)
    temp_input = f"temp_in_{file.filename}"
    temp_mono = f"temp_mono_{file.filename}.wav"
    try:
        with open(temp_input, "wb") as buffer:
            buffer.write(await file.read())
        y, sr = librosa.load(temp_input, sr=16000, mono=False)
        if y.ndim > 1: y_caller = y[0, :]
        else: y_caller = y
        b64_spectrogram = generate_spectrogram_base64(y_caller, sr)
        chunk_length = 4 * 16000
        num_chunks = len(y_caller) // chunk_length
        if num_chunks == 0: chunks = [y_caller]
        else: chunks = [y_caller[i*chunk_length:(i+1)*chunk_length] for i in range(num_chunks)]
        prob_fakes = []
        for chunk in chunks[:5]:
            sf.write(temp_mono, chunk, 16000)
            emb = speaker_model.get_embedding(temp_mono)
            emb_np = emb.squeeze().cpu().detach().numpy().reshape(1, -1)
            prob_fake = clf_model.predict_proba(emb_np)[0][0] 
            prob_fakes.append(prob_fake)
        avg_prob_fake = float(np.mean(prob_fakes))
        is_synthetic = bool(avg_prob_fake > 0.5)
        confidence = avg_prob_fake if is_synthetic else (1.0 - avg_prob_fake)
        return {"is_synthetic": is_synthetic, "confidence": round(confidence, 2), "spectrogram": b64_spectrogram}
    except Exception as e:
        return JSONResponse(content={"error": str(e)}, status_code=500)
    finally:
        if os.path.exists(temp_input): os.remove(temp_input)
        if os.path.exists(temp_mono): os.remove(temp_mono)

from fastapi import Request

@app.post("/detect")
async def detect_voice(request: Request):
    if not clf_model: return JSONResponse(content={"error": "El modelo no está cargado."}, status_code=500)
    
    # 1. Leer el audio en base64 (El PDF exige que sea base64, no un archivo directo)
    try:
        body_bytes = await request.body()
        # Intentar parsear como JSON por si mandan {"audio": "base64..."}
        import json
        try:
            data = json.loads(body_bytes.decode('utf-8'))
            b64_str = data.get("audio_base64", data.get("audio", data.get("data", data.get("file", data.get("clip", "")))))
        except json.JSONDecodeError:
            # Si no es JSON, asumir que todo el body es el string base64 crudo
            b64_str = body_bytes.decode('utf-8')
            
        if not b64_str:
            return JSONResponse(content={"error": "No base64 string provided"}, status_code=400)
            
        wav_bytes = base64.b64decode(b64_str)
    except Exception as e:
        return JSONResponse(content={"error": f"Failed to decode base64: {str(e)}"}, status_code=400)

    temp_input = f"temp_in_strict_{uuid.uuid4().hex}.wav"
    temp_mono = f"temp_mono_strict_{uuid.uuid4().hex}.wav"
    try:
        with open(temp_input, "wb") as buffer: 
            buffer.write(wav_bytes)
            
        y, sr = librosa.load(temp_input, sr=16000, mono=False)
        if y.ndim > 1: y_caller = y[0, :]
        else: y_caller = y
        
        chunk_length = 4 * 16000
        num_chunks = len(y_caller) // chunk_length
        if num_chunks == 0: chunks = [y_caller]
        else: chunks = [y_caller[i*chunk_length:(i+1)*chunk_length] for i in range(num_chunks)]
        
        prob_fakes = []
        for chunk in chunks[:5]:
            sf.write(temp_mono, chunk, 16000)
            emb = speaker_model.get_embedding(temp_mono)
            emb_np = emb.squeeze().cpu().detach().numpy().reshape(1, -1)
            prob_fakes.append(clf_model.predict_proba(emb_np)[0][0])
            
        avg_prob_fake = float(np.mean(prob_fakes))
        is_synthetic = bool(avg_prob_fake > 0.5)
        confidence = avg_prob_fake if is_synthetic else (1.0 - avg_prob_fake)
        return {"is_synthetic": is_synthetic, "confidence": round(confidence, 2)}
    except Exception as e:
        return JSONResponse(content={"error": str(e)}, status_code=500)
    finally:
        if os.path.exists(temp_input): os.remove(temp_input)
        if os.path.exists(temp_mono): os.remove(temp_mono)


@app.post("/detect_stream")
async def detect_stream(file: UploadFile = File(...)):
    import tempfile, os, librosa, numpy as np, soundfile as sf
    temp_input = tempfile.mktemp(suffix=".webm")
    temp_mono = tempfile.mktemp(suffix=".wav")
    try:
        with open(temp_input, "wb") as f:
            f.write(await file.read())
        
        y, sr = librosa.load(temp_input, sr=16000, mono=False)
        if y.ndim > 1: y_caller = y[0, :]
        else: y_caller = y
        
        sf.write(temp_mono, y_caller, 16000)
        
        emb = speaker_model.get_embedding(temp_mono)
        emb_np = emb.squeeze().cpu().detach().numpy().reshape(1, -1)
        
        pred = clf_model.predict(emb_np)[0]
        prob = clf_model.predict_proba(emb_np)[0]
        
        is_synthetic = bool(pred == 0)
        confidence = float(prob[0] if is_synthetic else prob[1])
        
        return {"is_synthetic": is_synthetic, "confidence": confidence}
    except Exception as e:
        print("STREAM ERROR:", str(e))
        return {"error": str(e)}
    finally:
        if os.path.exists(temp_input): os.remove(temp_input)
        if os.path.exists(temp_mono): os.remove(temp_mono)

